tool_input.command:
$js=@'
const fs=require("fs"),path=require("path");
const dir=process.env.USERPROFILE+"/.dsh/storages/session_projcache/sessions";
function scan(days){const h={};let n=0;const cut=days?Date.now()-days*86400000:0;
for(const f of fs.readdirSync(dir)){try{const p=path.join(dir,f);const st=fs.statSync(p);if(days&&st.mtimeMs<cut)continue;const c=fs.readFileSync(p,"utf8");const m=c.match(/"skills":\s*\{([^{}]*)\}/);if(!m||!m[1].trim())continue;n++;for(const kv of m[1].matchAll(/"([^"]+)"\s*:\s*true/g)){h[kv[1]]=(h[kv[1]]||0)+1;}}catch(e){}}
return {n,h};}
for(const [label,days] of [["ALL",0],["LAST30D",30],["LAST7D",7]]){const {n,h}=scan(days);console.log(`\n=== ${label} (sessionsWithSkill=${n}) ===`);Object.entries(h).sort((a,b)=>b[1]-a[1]).slice(0,20).forEach(([k,v])=>console.log(String(v).padStart(4)+"  "+k));}
'@; $js | Out-File -FilePath "$env:TEMP\skillfreq.js" -Encoding utf8; node "$env:TEMP\skillfreq.js"

$js=@'
const fs=require("fs"),path=require("path");
const dir=process.env.USERPROFILE+"/.dsh/logs";const h={};
const plugins=["agent-guard","cost-meter","token-guard","orchestrator-gate","plan-gate","mcp-gateway","dcwhc","orchestrator","langgraph-orchestrator"];
for(const f of fs.readdirSync(dir)){try{const c=fs.readFileSync(path.join(dir,f),"utf8");for(const p of plugins){const n=(c.match(new RegExp(p.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),"g"))||[]).length;if(n)h[p]=(h[p]||0)+n;}}catch(e){}}
Object.entries(h).sort((a,b)=>b[1]-a[1]).forEach(([k,v])=>console.log(String(v).padStart(5)+"  "+k));
'@; $js|Out-File "$env:TEMP\pf.js" -Encoding utf8; node "$env:TEMP\pf.js"; Remove-Item "$env:TEMP\pf.js" -Force -EA SilentlyContinue
